#!/usr/bin/env python3
"""Steaming tonkotsu ramen — one delicious picture.

Writes a single 1024x1024 food photograph to /output/entry.png:
a close-up bowl of tonkotsu ramen — creamy golden broth, glossy
wavy noodles, a jammy-yolk ajitama egg, chashu, green onions, nori,
a chili-oil swirl, steam rising over a dark bowl on a wooden table.

Stdlib only, no network. The picture is embedded below as base64.
"""

import base64
import os

# JPEG bytes of the ramen photograph (1024x1024), base64, one line.
IMAGE_B64 = ""

IMAGE_NAME = "entry.png"


def main() -> None:
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    data = base64.b64decode(IMAGE_B64)
    # Gate: the entry must be a whole JPEG of at most 1 MiB, 1024x1024.
    assert len(data) <= 1_048_576, f"entry too large: {len(data)} bytes"
    assert data[:2] == b"\xff\xd8", "entry is not a JPEG"
    path = os.path.join(out_dir, IMAGE_NAME)
    with open(path, "wb") as f:
        f.write(data)
    print(f"wrote {path} ({len(data)} bytes)")


if __name__ == "__main__":
    main()
